// One webhook call carries one customer message that GHL has already stored.
// Ids for fields, tags, calendar and pipeline come from scripts/setup_ghl.py at deploy time.
const CFG = {{GHL_IDS_JSON}};
const DEFAULT_MODEL = '{{LLM_MODEL}}';
// The eval compares two models, so a caller with the token may pick one of these.
const MODELS = ['claude-haiku-5-5', 'claude-sonnet-5-5'];
const b = $input.first().json.body ?? {};
const text = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const out = {
  message_id: text(b.message_id, 100),
  conversation_id: text(b.conversation_id, 100),
  contact_id: text(b.contact_id, 100),
  body: text(b.body, 2000),
  model: MODELS.includes(b.model) ? b.model : DEFAULT_MODEL,
  started_at: Date.now(),
  cfg: CFG,
};
out.valid = Boolean(out.message_id && out.conversation_id && out.contact_id && out.body);
return [{ json: out }];

parameters.query:
select coalesce(json_agg(t), '[]'::json) as chunks from (
  select article_id, title, content, round(similarity::numeric, 3) as similarity
  from match_chunks($1::vector, 4)
) t

